describe('Async Error Retry Option', () => {
  beforeEach(() => {
    cy.visit('/api/data');
  });

  it('should display retry option when async operation fails', () => {
    // Intercept the initial API call and make it fail
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('initialFetch');

    // Trigger the async operation
    cy.get('[data-testid="fetch-button"]').click();

    // Wait for the failed API call
    cy.wait('@initialFetch');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to load data');

    // Verify retry button is visible
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').should('contain', 'Retry');

    // Verify retry button is disabled initially
    cy.get('[data-testid="retry-button"]').should('be.disabled');

    // Click retry button
    cy.get('[data-testid="retry-button"]').click();

    // Intercept the retry API call and make it succeed
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: { data: 'Successfully loaded data' }
    }).as('retryFetch');

    // Wait for the successful retry
    cy.wait('@retryFetch');

    // Verify error message is gone
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify data is displayed
    cy.get('[data-testid="data-display"]').should('be.visible');
    cy.get('[data-testid="data-display"]').should('contain', 'Successfully loaded data');

    // Verify retry button is no longer visible
    cy.get('[data-testid="retry-button"]').should('not.exist');
  });

  it('should handle multiple failed retries and disable retry button', () => {
    // Intercept the initial API call and make it fail
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('initialFetch');

    // Trigger the async operation
    cy.get('[data-testid="fetch-button"]').click();

    // Wait for the failed API call
    cy.wait('@initialFetch');

    // Verify error message and retry button appear
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Click retry button (first attempt)
    cy.get('[data-testid="retry-button"]').click();

    // Intercept the first retry and make it fail
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('retryFetch1');

    cy.wait('@retryFetch1');

    // Verify error message persists
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Click retry button (second attempt)
    cy.get('[data-testid="retry-button"]').click();

    // Intercept the second retry and make it fail
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('retryFetch2');

    cy.wait('@retryFetch2');

    // Verify retry button is disabled after max retries
    cy.get('[data-testid="retry-button"]').should('be.disabled');
    cy.get('[data-testid="retry-button"]').should('contain', 'Retry (Max attempts reached)');

    // Verify error message shows max attempts reached
    cy.get('[data-testid="error-message"]').should('contain', 'Max retries reached');
  });
});
